/**
 * The rules of the file views, with nothing in them that draws: which views there are, what a
 * file's status line says, how wide a grid tile is, how full the download pie is. Kept apart so
 * they can be tested without a screen, and so every app words and sizes things the same way.
 */

import { describeShareState, type ShareBar } from '../ShareState/shareState';

// ---------------------------------------------------------------------------------------------
// The views
// ---------------------------------------------------------------------------------------------

/**
 * The ways to see the same files. `expanded` is the roomy list (a picture, the name, a line of
 * detail); `list` is one tight line per file, like a folder in Finder; `grid` is pictures.
 *
 * More views (a social feed, a wall of pictures) are added to this list when an app needs them.
 * An app only ever shows the views it names in `modes`, so a view added for one app never
 * appears in another by itself.
 */
export type FileViewMode = 'list' | 'expanded' | 'grid';

export type FileViewChoice = {
  value: FileViewMode;
  /** Read out for the button: "List view". */
  label: string;
  /** The word in a list of the views: "List". */
  name: string;
  icon: 'view-list' | 'view-expanded' | 'view-grid';
};

export const FILE_VIEW_CHOICES: readonly FileViewChoice[] = [
  { value: 'list', label: 'List view', name: 'List', icon: 'view-list' },
  { value: 'expanded', label: 'Expanded view', name: 'Expanded', icon: 'view-expanded' },
  { value: 'grid', label: 'Grid view', name: 'Grid', icon: 'view-grid' },
];

export const DEFAULT_FILE_VIEW: FileViewMode = 'expanded';

/** The choices an app offers, in the standard order, whatever order it named them in. */
export function fileViewChoices(modes?: readonly FileViewMode[]): readonly FileViewChoice[] {
  if (!modes) return FILE_VIEW_CHOICES;
  return FILE_VIEW_CHOICES.filter((choice) => modes.includes(choice.value));
}

/** A saved choice read back: anything that is not one of the offered views becomes the fallback. */
export function fileViewFrom(
  saved: unknown,
  modes: readonly FileViewMode[] = FILE_VIEW_CHOICES.map((c) => c.value),
  fallback: FileViewMode = DEFAULT_FILE_VIEW
): FileViewMode {
  const known = modes.find((mode) => mode === saved);
  if (known) return known;
  return modes.includes(fallback) ? fallback : modes[0] ?? fallback;
}

/** The view after this one, for a single button that steps through them. */
export function nextFileView(current: FileViewMode, modes?: readonly FileViewMode[]): FileViewMode {
  const choices = fileViewChoices(modes);
  const at = choices.findIndex((choice) => choice.value === current);
  return choices[(at + 1) % choices.length]?.value ?? current;
}

/** Where a button is on the screen. */
export type ViewMenuAnchor = { x: number; y: number; width: number; height: number };

/**
 * Where the drop-down list of views goes: just under its button, its right edge on the button's
 * right edge, and never off either side of the screen.
 */
export function viewMenuPlace(
  anchor: ViewMenuAnchor,
  screenWidth: number,
  listWidth: number,
  { gap = 6, edge = 8 }: { gap?: number; edge?: number } = {}
): { top: number; left: number } {
  const wanted = anchor.x + anchor.width - listWidth;
  const most = Math.max(edge, screenWidth - listWidth - edge);
  return {
    top: Math.round(anchor.y + anchor.height + gap),
    left: Math.round(Math.min(most, Math.max(edge, wanted))),
  };
}

// ---------------------------------------------------------------------------------------------
// A file, as a view needs it
// ---------------------------------------------------------------------------------------------

/** The same six kinds as the `FileKind` of `Thumbnail`; named apart so both can be exported. */
export type FileViewKind = 'image' | 'video' | 'audio' | 'document' | 'folder' | 'file';

/** How the status line is coloured. `plain` is ordinary small text. */
export type FileTone = 'plain' | 'good' | 'busy' | 'bad';

/**
 * One file (or folder, or share) in a view. Every view draws from this one shape, so switching
 * views never changes what is known about a file, only how much of it is shown.
 *
 * `Extra` is the app's own record, carried along untouched and handed back when the file is
 * opened; the views never look inside it.
 */
export type FileViewItem<Extra = unknown> = {
  id: string;
  name: string;
  kind: FileViewKind;
  /** The one short line about the file's state: "Active", "Downloading 48%", "Sharing 12%". */
  status?: string | null;
  /**
   * The same state in fewer letters, for the grid, where a line holds about a dozen. The grid
   * shows it in place of `status` when it is given.
   */
  shortStatus?: string | null;
  tone?: FileTone;
  /**
   * How much of the file has arrived, 0 to 1, and only while it is downloading. This is what
   * draws the pie over the picture. Leave it out for a file that is here, and for an upload.
   */
  download?: number | null;
  /**
   * The progress bar under the status line in the expanded view, or nothing for none. It comes
   * from `describeShareState` (or `transferBar`), which also says how it is drawn.
   */
  bar?: ShareBar | null;
  /** More about the file for the expanded view: its size, its age. */
  detail?: string | null;
  /** A picture of the file, when there is one. */
  thumbnail?: string | null;
  /** Drawn fainter: a share that is switched off, a file that is not here. */
  dim?: boolean;
  /** Ticked, while the app is letting the user pick several. */
  selected?: boolean;
  extra?: Extra;
};

/** The kind of a file, from its name. An app with better knowledge passes the kind itself. */
export function fileViewKindOf(name: string): FileViewKind {
  const dot = name.lastIndexOf('.');
  const ext = dot >= 0 ? name.slice(dot + 1).toLowerCase() : '';
  if (['jpg', 'jpeg', 'png', 'gif', 'webp', 'heic', 'heif', 'bmp', 'avif', 'svg'].includes(ext))
    return 'image';
  if (['mp4', 'mov', 'm4v', 'mkv', 'avi', 'webm'].includes(ext)) return 'video';
  if (['mp3', 'm4a', 'aac', 'wav', 'flac', 'ogg', 'opus', 'aiff'].includes(ext)) return 'audio';
  if (['pdf', 'txt', 'md', 'doc', 'docx', 'rtf', 'pages', 'csv', 'json', 'html'].includes(ext))
    return 'document';
  return 'file';
}

// ---------------------------------------------------------------------------------------------
// The status line
// ---------------------------------------------------------------------------------------------

export type TransferReading = {
  /** `up`: this device is giving the file. `down`: it is taking it. */
  direction: 'up' | 'down';
  /** 0 to 100, or null when it is not known yet. */
  percent: number | null;
  /** The whole file has moved. */
  done: boolean;
};

function wholePercent(percent: number | null): number | null {
  if (percent == null || !Number.isFinite(percent)) return null;
  return Math.round(Math.min(100, Math.max(0, percent)));
}

/**
 * The few words that say where a transfer stands, in the universal words of `ShareState`. One
 * state at a time, never a chain of them: "Sharing 12%" while it goes up, "Downloading 12%"
 * while it comes down, and "Active" once the whole file is where it was going.
 *
 * `short` is for the grid, where a line holds about a dozen letters: a download drops its
 * number there, because the pie over the picture already shows it.
 */
export function transferStatus(reading: TransferReading, options: { short?: boolean } = {}): string {
  const view = transferState(reading);
  return options.short ? view.shortLabel : view.label;
}

/** The whole universal state of a transfer: its words, its colour and its bar. */
export function transferState(reading: TransferReading) {
  if (reading.done) return describeShareState({ kind: 'active' });
  return describeShareState({
    kind: reading.direction === 'up' ? 'sharing' : 'downloading',
    percent: reading.percent,
  });
}

/** What to give a file as `tone`: amber while it moves, green once it is done. */
export function transferTone(reading: TransferReading): FileTone {
  return transferState(reading).tone;
}

/** What to give a file as `bar`: the progress bar of a transfer that is still going. */
export function transferBar(reading: TransferReading | null | undefined): ShareBar | null {
  return reading ? transferState(reading).bar : null;
}

/**
 * What to give a file as `download`: how full the pie is, or null for no pie. Only a download
 * that is still going has one; an upload never does (its progress is in the status line).
 */
export function downloadPie(reading: TransferReading | null | undefined): number | null {
  if (!reading || reading.direction !== 'down' || reading.done) return null;
  const percent = wholePercent(reading.percent);
  return percent == null ? 0 : percent / 100;
}

// ---------------------------------------------------------------------------------------------
// Sizes
// ---------------------------------------------------------------------------------------------

/** The height of one line in the list view. */
export const LIST_ROW_HEIGHT = 40;
/** The picture beside a name in the list view. */
export const LIST_THUMB = 24;
/** The picture in the expanded view. */
export const EXPANDED_THUMB = 48;
export const EXPANDED_ROW_HEIGHT = 72;

export type GridMetrics = {
  columns: number;
  /** The side of one square picture. */
  tile: number;
  /** The space between two tiles, and between two rows. */
  gap: number;
  /** The space at each edge of the screen. */
  edge: number;
};

/**
 * The three sizes of grid a person can choose between: the number is how many pictures fit
 * across. Medium is the standing choice.
 */
export type GridSize = 'large' | 'medium' | 'small';

export type GridSizeChoice = { value: GridSize; /** The word in a setting: "Medium". */ name: string; columns: number };

export const GRID_SIZES: readonly GridSizeChoice[] = [
  { value: 'large', name: 'Large', columns: 3 },
  { value: 'medium', name: 'Medium', columns: 4 },
  { value: 'small', name: 'Small', columns: 5 },
];

export const DEFAULT_GRID_SIZE: GridSize = 'medium';
export const DEFAULT_GRID_COLUMNS = 4;

/** A saved size read back: anything that is not one of the three becomes the standing choice. */
export function gridSizeFrom(saved: unknown): GridSize {
  return GRID_SIZES.find((choice) => choice.value === saved)?.value ?? DEFAULT_GRID_SIZE;
}

/** How many pictures across a size is. */
export function gridColumns(size: GridSize): number {
  return GRID_SIZES.find((choice) => choice.value === size)?.columns ?? DEFAULT_GRID_COLUMNS;
}

/**
 * How a grid fits a screen: four pictures across by default, whatever the width. The tile is a
 * whole number of points, so pictures land on whole pixels and their edges stay sharp.
 */
export function gridMetrics(
  width: number,
  options: { columns?: number; gap?: number; edge?: number } = {}
): GridMetrics {
  const columns = Math.max(1, Math.floor(options.columns ?? DEFAULT_GRID_COLUMNS));
  const gap = options.gap ?? 10;
  const edge = options.edge ?? 12;
  const room = Math.max(0, width - edge * 2 - gap * (columns - 1));
  return { columns, tile: Math.max(1, Math.floor(room / columns)), gap, edge };
}

export type GridText = {
  /** The size of the name under a picture, and the height of its line. */
  name: number;
  nameLine: number;
  /** The size of the status under the name, and the height of its line. */
  status: number;
  statusLine: number;
};

/**
 * The two lines under a grid picture grow with the picture: small enough on a phone that
 * "Downloading" fits under a tile a fifth of the screen wide, larger on a tablet or a desk.
 */
export function gridText(tile: number): GridText {
  const tenth = (value: number) => Math.round(value * 10) / 10;
  const name = tenth(Math.min(13, Math.max(10, tile * 0.165)));
  const status = tenth(Math.min(12, Math.max(9, tile * 0.142)));
  return { name, nameLine: Math.ceil(name * 1.3), status, statusLine: Math.ceil(status * 1.3) };
}

/** The smallest a status may be shrunk to, as a share of its usual size, to fit under its picture. */
export const GRID_STATUS_SHRINK = 0.8;

/**
 * The size a line of text must be to fit a width, by a rough count of its letters. A phone
 * measures the real text and shrinks it itself; this is for the web, which cannot.
 */
export function fitTextSize(
  text: string,
  width: number,
  size: number,
  least = size * GRID_STATUS_SHRINK
): number {
  if (!text.length || width <= 0) return size;
  const fits = width / (text.length * 0.68);
  return Math.round(Math.max(least, Math.min(size, fits)) * 10) / 10;
}

/** The height of one grid cell: the picture, then the name, then the status. */
export function gridCellHeight(tile: number): number {
  const text = gridText(tile);
  return tile + GRID_TEXT_GAP + text.nameLine + text.statusLine;
}
export const GRID_TEXT_GAP = 5;
/** How far the two lines of text reach past each side of the picture, into the space between tiles. */
export const GRID_TEXT_SPILL = 4;

/**
 * The filled part of the download pie as an SVG path: a slice that starts at twelve o'clock and
 * grows clockwise. Nothing for an empty pie, a whole disc for a full one.
 */
export function pieSlice(fraction: number, radius: number, cx: number, cy: number): string {
  const part = Math.min(1, Math.max(0, Number.isFinite(fraction) ? fraction : 0));
  if (part <= 0) return '';
  const n = (value: number) => String(Math.round(value * 100) / 100);
  if (part >= 1) {
    return `M${n(cx - radius)} ${n(cy)}A${n(radius)} ${n(radius)} 0 1 1 ${n(cx + radius)} ${n(cy)}A${n(
      radius
    )} ${n(radius)} 0 1 1 ${n(cx - radius)} ${n(cy)}Z`;
  }
  const angle = part * 2 * Math.PI;
  const x = cx + radius * Math.sin(angle);
  const y = cy - radius * Math.cos(angle);
  return `M${n(cx)} ${n(cy)}L${n(cx)} ${n(cy - radius)}A${n(radius)} ${n(radius)} 0 ${
    part > 0.5 ? 1 : 0
  } 1 ${n(x)} ${n(y)}Z`;
}

// ---------------------------------------------------------------------------------------------
// Where the files come from
// ---------------------------------------------------------------------------------------------

/**
 * A place files can be listed from: a folder on this device, or a key on the network (a
 * Hyperdrive, or a pearcore space). The views themselves never read either; the app supplies a
 * reader that does (see `FileReader`), and the views draw whatever it returns.
 */
export type FileSource =
  | { from: 'disk'; folder: string }
  | { from: 'key'; key: string; network: 'hyperdrive' | 'pearcore' };

/**
 * What an app writes once for each kind of place it can list. `list` returns the files as the
 * views need them; `watch` (optional) calls back when the place changes, and returns a function
 * that stops watching.
 */
export type FileReader<Extra = unknown> = {
  list: (source: FileSource) => Promise<FileViewItem<Extra>[]>;
  watch?: (source: FileSource, onChange: () => void) => () => void;
};

/** A name for a source that is the same for the same place, to tell when the place has changed. */
export function fileSourceKey(source: FileSource): string {
  return source.from === 'disk' ? `disk:${source.folder}` : `${source.network}:${source.key}`;
}
